query.query:
query Query($reportId: String!) {
  qualityReport(where: {id: {_eq: $reportId}}) {
    edges {
      node {
        subjectList{
          sampleSize
        }
        qualitySpecificationGroup {
          name
          specifications {
            edges {
              node {
                specification {
                  id
                  name
                  imageId
                  lowerBound
                  upperBound
                  usable
                  code
                  description
                  fileId
                  expectedValue
                  typeId
                  unit{
                    name
                  }
                  qualityChecks (where: {reportId: {_eq: $reportId}}) {
                    edges {
                      node {
                        id
                        complete
                        result
                        note
                        value
                        qualitySpecificationId
                        reportId
                      }
                    }
                  }
                }
              }
            }
          }
        }
      }
    }
  }
}

transforms.pre:
{
  "REQUEST": {
    "DATA": {
      "reportId": $metadata.urlParameters.id,
      "values": {
        $parent.data.name: $parent.data.typeId = "Number" ? 
        $tryCatch(
          function($value){
            $value.($ ~> $trim ~> $number)
          },
          function($err, $value){
            $throw("Check value(s): " & $value & " is not a valid number.")
          }
        )($components.CheckTable.data.check) 
        : $parent.data.typeId = "Boolean" ?
        (
          $defaultSamples := $count($parent.data.qualityChecks.edges.node[complete=false]) - $count($components.CheckTable.data.check);
          $defaultSamples > 0 ?
          $components.CheckTable.data.check ~> $append([1..$defaultSamples].(false))
          : $components.CheckTable.data.check       
        )
        : $components.CheckTable.data.check 
      },
      "notes": $components.CheckTable.data.note
    },

    "ACTION": "UPDATE"
  }
}

action.query:
query Query($where: EmployeeWhereInput, $orderBy: [EmployeeOrderByInput!], $first: Int, $after: String) {
  employee(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        id
      }
    }
  }
}

query Query($where: ProductionRunWhereInput) {
  productionRun(where: $where) {
    edges {
      node {
        id
        productionHistories{
          edges{
            node{
              inventoryId
            }
          }
        }
      }
    }
  }
}

action.mutation:
mutation Mutation($payload: [QualityReportInventoryCreatePayloadInput!]!) {
  createQualityReportInventory(payload: $payload) {
    id
    inventoryId
    qualityReportId
  }
}

transforms.pre:
data.serialNumber in data.productionRun.edges.node.productionHistories.edges.node.inventoryId ? {
  "payload": {
    "create": {
      "qualityReportId": $components.ReportForm.data.id,
      "inventoryId": data.serialNumber
    }
  }
}
: $throw("The scanned Serial Number: " & data.serialNumber &" is not from this Production Run.")
